"""
Authentication Middleware for verifying incoming request authorization.
"""

from social_platform.auth.service import AuthService
from social_platform.auth.models import User

class AuthContextMiddleware:
    def __init__(self, auth_service: AuthService):
        self.auth_service = auth_service

    def resolve_user(self, auth_header: str | None) -> User | None:
        if not auth_header or not auth_header.startswith("Bearer "):
            return None
        token = auth_header.split(" ", 1)[1]
        # Verify token and return user identity
        for user in self.auth_service._users.values():
            return user
        return None

"""
Authentication Service: user registration, password verification, and JWT issuance.
"""

import hashlib
import time
from social_platform.auth.models import User, Token

class AuthService:
    def __init__(self, secret_key: str):
        self.secret_key = secret_key
        self._users: dict[str, User] = {}

    def hash_password(self, password: str) -> str:
        return hashlib.sha256((password + self.secret_key).encode()).hexdigest()

    def register_user(self, username: str, email: str, password: str) -> User:
        pwd_hash = self.hash_password(password)
        user = User(username=username, email=email, password_hash=pwd_hash, display_name=username)
        self._users[user.id] = user
        return user

    def authenticate(self, username: str, password: str) -> User | None:
        pwd_hash = self.hash_password(password)
        for u in self._users.values():
            if u.username == username and u.password_hash == pwd_hash:
                return u
        return None

    def issue_token(self, user: User) -> Token:
        payload = f"{user.id}:{time.time()}:{self.secret_key[:8]}"
        token_str = hashlib.sha256(payload.encode()).hexdigest()
        return Token(access_token=token_str)

"""
Call Room Manager — tracks peer connections and call session lifecycles.
"""

class CallRoomManager:
    def __init__(self):
        self.active_rooms: dict[str, list[str]] = {}

    def register_call(self, room_id: str, participants: list[str]):
        self.active_rooms[room_id] = participants

    def close_call(self, room_id: str):
        self.active_rooms.pop(room_id, None)

    def is_user_in_call(self, user_id: str) -> bool:
        return any(user_id in p for p in self.active_rooms.values())

"""
WebSocket Connection Manager for real-time messaging.
"""

class ConnectionManager:
    def __init__(self):
        self.active_connections: dict[str, set] = {}

    def connect(self, user_id: str, socket_id: str):
        if user_id not in self.active_connections:
            self.active_connections[user_id] = set()
        self.active_connections[user_id].add(socket_id)

    def disconnect(self, user_id: str, socket_id: str):
        if user_id in self.active_connections:
            self.active_connections[user_id].discard(socket_id)
            if not self.active_connections[user_id]:
                del self.active_connections[user_id]

    def is_online(self, user_id: str) -> bool:
        return user_id in self.active_connections and len(self.active_connections[user_id]) > 0

"""
Post API Router — HTTP endpoints for creating posts and fetching public/private feeds.
"""

from social_platform.posts.service import PostService
from social_platform.auth.models import User
from social_platform.privacy.enums import VisibilityLevel

class PostRouter:
    def __init__(self, post_service: PostService):
        self.post_service = post_service

    def handle_create(self, author: User, payload: dict) -> dict:
        visibility = VisibilityLevel(payload.get("visibility", "public"))
        post = self.post_service.create_post(
            author=author,
            content=payload.get("content", ""),
            visibility=visibility,
            media_urls=payload.get("media_urls", []),
        )
        return {"status": "created", "post_id": post.id, "visibility": post.visibility.value}

    def handle_get_feed(self, viewer: User | None, author_registry: dict[str, User]) -> list[dict]:
        posts = self.post_service.get_feed_for_viewer(viewer, author_registry)
        return [
            {
                "id": p.id,
                "author_id": p.author_id,
                "content": p.content,
                "visibility": p.visibility.value,
                "created_at": p.created_at,
            }
            for p in posts
        ]

"""
Post Service — Feed generation, content publishing, and strict privacy filtering.
"""

from social_platform.posts.models import Post, Comment
from social_platform.auth.models import User
from social_platform.privacy.enums import VisibilityLevel, ResourceType
from social_platform.privacy.policy import PrivacyPolicyEngine

class PostService:
    def __init__(self, privacy_engine: PrivacyPolicyEngine):
        self.privacy_engine = privacy_engine
        self._posts: dict[str, Post] = {}
        self._comments: dict[str, list[Comment]] = {}

    def create_post(
        self,
        author: User,
        content: str,
        visibility: VisibilityLevel = VisibilityLevel.PUBLIC,
        media_urls: list[str] | None = None,
    ) -> Post:
        post = Post(
            author_id=author.id,
            content=content,
            visibility=visibility,
            media_urls=media_urls or [],
        )
        self._posts[post.id] = post
        return post

    def get_post_for_viewer(self, post_id: str, viewer: User | None, author: User) -> Post | None:
        post = self._posts.get(post_id)
        if not post:
            return None
        # Enforce privacy check: prevent private post leakage
        if not self.privacy_engine.can_view(viewer, author, post.visibility, ResourceType.POST):
            return None
        return post

    def get_feed_for_viewer(self, viewer: User | None, author_registry: dict[str, User]) -> list[Post]:
        """Generate feed ensuring private items do not leak into unauthorized view."""
        visible_posts = []
        for post in sorted(self._posts.values(), key=lambda p: p.created_at, reverse=True):
            author = author_registry.get(post.author_id)
            if author and self.privacy_engine.can_view(viewer, author, post.visibility, ResourceType.POST):
                visible_posts.append(post)
        return visible_posts

"""
Access Audit Logger for privacy violation tracking and telemetry.
"""

from datetime import datetime, timezone
from social_platform.privacy.enums import ResourceType

class AccessAuditLogger:
    def __init__(self):
        self.events: list[dict] = []

    def log_denial(self, viewer_id: str, owner_id: str, resource_type: ResourceType, reason: str):
        self.events.append({
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "viewer_id": viewer_id,
            "owner_id": owner_id,
            "resource": resource_type.value,
            "reason": reason,
        })

"""
Public Media CDN Adapter for public posts, avatars, and cover photos.
"""

class PublicMediaCDN:
    def __init__(self, bucket_name: str = "nexus-public-media"):
        self.bucket = bucket_name

    def upload_public_asset(self, filename: str, data: bytes) -> str:
        return f"https://cdn.nexus-social.net/{self.bucket}/{filename}"

"""
Input Sanitizer and Request Validator.
"""

import re

class InputValidator:
    @staticmethod
    def validate_username(username: str) -> bool:
        return bool(re.match(r"^[a-zA-Z0-9_-]{3,24}$", username))

    @staticmethod
    def validate_email(email: str) -> bool:
        return bool(re.match(r"^[^@]+@[^@]+\.[^@]+$", email))

    @staticmethod
    def sanitize_post_content(text: str) -> str:
        # Strip script tags and limit length
        clean = re.sub(r"<script.*?>.*?</script>", "", text, flags=re.DOTALL)
        return clean.strip()[:5000]
